<script setup lang="ts">
const { data: me }=await useFetch('/api/auth/me'); if(!me.value?.authenticated) await navigateTo('/login')
const form=reactive({event_name:'',channel:'',event_date:'',request_type:'stream'}); const sent=ref(false); const error=ref('')
async function submit(){error.value='';sent.value=false;try{await $fetch('/api/requests',{method:'POST',body:form});sent.value=true;Object.assign(form,{event_name:'',channel:'',event_date:'',request_type:'stream'})}catch(e:any){error.value=e?.data?.message||'Request gagal dikirim.'}}
</script>
<template><div class="mx-auto max-w-2xl"><section class="rounded-2xl border border-slate-800 bg-gradient-to-r from-indigo-950/50 to-slate-900 p-6 sm:p-8"><p class="text-xs font-black uppercase tracking-[.22em] text-indigo-400">Community request</p><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="mt-2 text-3xl font-black">Request an event</h1><p class="mt-2 muted">Tell the team what you'd like to see. Your request is linked to {{me?.email}}.</p></div><NuxtLink to="/my-requests" class="text-sm font-bold text-indigo-300">My Requests →</NuxtLink></div></section><form @submit.prevent="submit" class="card mt-5 space-y-4 p-6"><label class="block"><span class="mb-2 block text-sm font-bold">Event name</span><input v-model="form.event_name" required class="input" placeholder="e.g. Championship Final"></label><label class="block"><span class="mb-2 block text-sm font-bold">Channel / network</span><input v-model="form.channel" class="input" placeholder="Optional"></label><label class="block"><span class="mb-2 block text-sm font-bold">Event date</span><input v-model="form.event_date" type="datetime-local" required class="input"></label><label class="block"><span class="mb-2 block text-sm font-bold">Request type</span><select v-model="form.request_type" class="input"><option value="stream">Live stream</option><option value="vod">VOD</option></select></label><button class="btn-primary w-full">Submit request</button><p v-if="sent" class="rounded-xl border border-emerald-900/60 bg-emerald-950/30 p-3 text-sm text-emerald-300">Request submitted. Status: Pending.</p><p v-if="error" class="rounded-xl border border-red-900/60 bg-red-950/30 p-3 text-sm text-red-400">{{error}}</p></form></div></template>
